// --- CONFIGURATION ---
// We build the position vector from u and v (already provided by the system)
// We multiply by 8.0 to "zoom out" and see more detail
vec2 p = vec2(u, v) * 8.0;

// --- DISTORTION (Domain Warping) ---
// We compute a base noise value
float n1 = sys_noise(p);

// We use the noise to shift the coordinates of the next step
// This creates the fluid/liquid effect
vec2 shift = vec2(n1, sys_noise(p + vec2(5.0, 5.0))); 

// --- PATTERN FINALE ---
// Calcoliamo il rumore finale sulle coordinate distorte
float pattern = sys_noise(p + shift * 2.0);

// --- CONTRASTO ---
// Rendiamo i bordi più netti (taglia i grigi intermedi)
pattern = smoothstep(0.3, 0.7, pattern);

// --- COLOR ---
// Uses the colors you chose in the panel (Color 1 and Color 2)
return mix(u_col1, u_col2, pattern);
